\newcommand{\myNonConvexPolyhedron}[1]{
	\begin{scope}[scale=#1]
		\coordinate (A) at ({2*cos(0*60)},0,{2*sin(0*60)}); 
		\coordinate (B) at ({2*cos(1*60)},0,{2*sin(1*60)});
		\coordinate (C) at ({2*cos(2*60)},0,{2*sin(2*60)});
		\coordinate (D) at ({2*cos(3*60)},0,{2*sin(3*60)});
		\coordinate (E) at ({2*cos(4*60)},0,{2*sin(4*60)});
		\coordinate (F) at ({2*cos(5*60)},0,{2*sin(5*60)});

		\coordinate (G) at ({2*cos(0*60)},2,{2*sin(0*60)}); 
		\coordinate (H) at ({2*cos(1*60)},2,{2*sin(1*60)});
		\coordinate (I) at ({2*cos(2*60)},2,{2*sin(2*60)});
		\coordinate (J) at ({2*cos(3*60)},2,{2*sin(3*60)});
		\coordinate (K) at ({2*cos(4*60)},2,{2*sin(4*60)});
		\coordinate (L) at ({2*cos(5*60)},2,{2*sin(5*60)});

		\coordinate (M) at ({2*cos(80)},1,{2*sin(80)});
		\coordinate (N) at ({2*cos(100)},1,{2*sin(100)});
		\coordinate (O) at ({2*cos(4*60+20)},1,{2*sin(4*60+20)});
		\coordinate (P) at ({2*cos(4*60+40)},1,{2*sin(4*60+40)});

		%\tkzLabelPoints[below left](A);\tkzLabelPoints[below right](B);
		%\tkzLabelPoints[right](C);\tkzLabelPoints[left](D);
		%\tkzLabelPoints[right](E);\tkzLabelPoints[right](F);
		%\tkzLabelPoints[below right](G);\tkzLabelPoints[right](H);
		%\tkzLabelPoints[right](I);\tkzLabelPoints[right](J);
		%\tkzLabelPoints[right](K);\tkzLabelPoints[right](L);

		% Faces
		\tkzDrawPolygon[draw=none, fill=deepskyblue!15, fill opacity=0.85](A,B,C,D,E,F)
		\tkzDrawPolygon[draw=none, fill=deepskyblue!15, fill opacity=0.85](E,K,O,P,L,F)
		\tkzDrawPolygon[draw=none, fill=deepskyblue!15, fill opacity=0.85](L,F,A,G)
		\tkzDrawPolygon[draw=none, fill=deepskyblue!15, fill opacity=0.85](K,E,D,J)
		\tkzDrawPolygon[draw=none, fill=deepskyblue!15, fill opacity=0.85](D,J,C,I)
		\tkzDrawPolygon[draw=none, fill=deepskyblue!15, fill opacity=0.85](A,B,C,I,N,M,H,G)
		\tkzDrawPolygon[draw=none, fill=deepskyblue!15, fill opacity=0.85](I,J,K)
		\tkzDrawPolygon[draw=none, fill=deepskyblue!15, fill opacity=0.85](L,G,H)
		\tkzDrawPolygon[draw=none, fill=deepskyblue!15, fill opacity=0.85](I,K,O,P,L,H,M,N)


	\tkzDrawSegments[very thick, color=deepskyblue](A,B B,C C,D G,H I,J J,K L,G L,H I,K N,O)
	\tkzDrawSegments[very thick, color=deepskyblue](A,G B,H C,I D,J)
		\tkzDrawSegments[thin, color=deepskyblue, dashed, opacity=0.75](M,P L,F F,E K,E D,E E,F F,A L,P P,O)
	\tkzDrawSegments[very thick, color=deepskyblue, shorten > =0.25cm](O,P)

		% Curve
		\draw [very thick, color=deepskyblue] (I)-- (N) -- (M) -- (H);
		\draw [very thick, color=deepskyblue] (K) -- (O);
		%\draw [very thick, color=deepskyblue] (P) -- (Q) -- (R) -- (G);
	\end{scope}
}

\newcommand{\myRecPrism}[6]{
	\begin{scope}[scale=#6]
		\coordinate (A) at (0,0,0);
		\coordinate (B) at (#1,0,0);
		\coordinate (C) at (#1,0,-#2);
		\coordinate (D) at (0,0,-#2);
		\coordinate (E) at (0,#3,0);
		\coordinate (F) at (#1,#3,0);
		\coordinate (H) at (0,#3,-#2);
		\coordinate (G) at (#1,#3,-#2);

		\tkzDrawPolygon[draw=none, color=#4, fill=#4!45, fill opacity=#5](A,B,C,D)
		\tkzDrawPolygon[draw=none, color=#4, fill=#4!15, fill opacity=#5](A,D,H,E)
		\tkzDrawPolygon[draw=none, color=#4, fill=#4!15, fill opacity=#5](D,C,G,H)
		\tkzDrawPolygon[very thick, color=#4, fill=#4!15, fill opacity=#5](A,B,F,E)
		\tkzDrawPolygon[very thick, color=#4, fill=#4!15, fill opacity=#5](B,C,G,F)
		\tkzDrawPolygon[very thick, color=#4, fill=#4!15, fill opacity=#5](F,G,H,E)
		\tkzDrawSegments[thin, color=#4, dashed, opacity=0.75](A,D H,D C,D)

%		\tkzLabelPoints[below left](A);\tkzLabelPoints[below right](B);
%		\tkzLabelPoints[right](C);\tkzLabelPoints[left](D);
%		\tkzLabelPoints[above left](E);\tkzLabelPoints[above](F);
%		\tkzLabelPoints[above right](G);\tkzLabelPoints[above left](H);		
	\end{scope}
}

