\newcommand{\myHeptPyramid}[6]{
	\begin{scope}[scale=#5]
		\def\StartAngle{0}	
		\pgfmathsetmacro{\alpha}{360/7};  

		\coordinate (A0) at (#1,0,0);
		\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+1*\alpha)};  
		\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+1*\alpha)/3};
		\coordinate (A1) at (\xc,\yc,0);
		\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+2*\alpha)};  
		\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+2*\alpha)/3};
		\coordinate (A2) at (\xc,\yc,0);
		\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+3*\alpha)};  
		\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+3*\alpha)/3};
		\coordinate (A3) at (\xc,\yc,0);
		\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+4*\alpha)};  
		\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+4*\alpha)/3};
		\coordinate (A4) at (\xc,\yc,0);
		\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+5*\alpha)};  
		\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+5*\alpha)/3};
		\coordinate (A5) at (\xc,\yc,0);
		\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+6*\alpha)};  
		\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+6*\alpha)/3};
		\coordinate (A6) at (\xc,\yc,0);
		\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+7*\alpha)};  
		\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+7*\alpha)/3};
		\coordinate (S) at (0,#2,0);

		% Faces
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A0,A1,S)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A1,A2,S)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A2,A3,S)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A3,A4,S)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A4,A5,S)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A5,A6,S)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A6,A0,S)

		% Base
		\tkzDrawPolygon[draw=none, fill=#3!25, fill opacity=#4](A0,A1,A2,A3,A4,A5,A6)

		% Edges
		\tkzDrawSegments[thin, color=#3, dashed, opacity=0.75](A0,A1 A1,A2 A2,A3)		
		\tkzDrawSegments[very thick, color=#3](A3,A4 A4,A5 A5,A6 A6,A0)

		\tkzDrawSegments[thin, color=#3, dashed, opacity=0.75](S,A1 S,A2)
		\tkzDrawSegments[very thick, color=#3](S,A0 S,A3 S,A4 S,A5 S,A6)


		%		\tkzLabelPoints[above](S);
	\end{scope}
}


