\newcommand{\myPentaPyramid}[5]{
	\begin{scope}[scale=#5, rotate=0]
	    \def\StartAngle{15}	
    	\pgfmathsetmacro{\alpha}{360/5};

		\coordinate (A0) at (#1,0);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+1*\alpha)};
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+1*\alpha)/3};
		\coordinate (A1) at (\xc,\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+2*\alpha)};
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+2*\alpha)/3};
		\coordinate (A2) at (\xc,\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+3*\alpha)};
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+3*\alpha)/3};
		\coordinate (A3) at (\xc,\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+4*\alpha)};
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+4*\alpha)/3};
		\coordinate (A4) at (\xc,\yc);

		\coordinate (A5) at (#1,-#2);
            \pgfmathsetmacro{\xc}{#1*cos(\StartAngle+1*\alpha)};
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+1*\alpha)/3};
		\coordinate (A6) at (\xc,-#2+\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+2*\alpha)};
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+2*\alpha)/3};
		\coordinate (A7) at (\xc,-#2+\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+3*\alpha)};
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+3*\alpha)/3};
		\coordinate (A8) at (\xc,-#2+\yc);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+4*\alpha)};
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+4*\alpha)/3};
		\coordinate (A9) at (\xc,-#2+\yc);


		% Faces
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A0,A1,A6,A5)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A1,A2,A7,A6)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A2,A3,A8,A7)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A3,A4,A9,A8)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A4,A0,A5,A9)

		% Base
		\tkzDrawPolygon[draw=none, fill=#3!25, fill opacity=#4](A0,A1,A2,A3,A4)
        % top
		\tkzDrawPolygon[draw=none, fill=#3!25, fill opacity=#4](A5,A6,A7,A8,A9)

		% Edges
		\tkzDrawSegments[thin, color=#3, dashed, opacity=0.75](A1,A6)		
		\tkzDrawSegments[very thick, color=#3](A0,A1 A1,A2 A2,A3 A3,A4 A4,A0)

        \tkzDrawSegments[very thick, color=#3](A7,A2 A5,A0 A3,A8 A4,A9)

		\tkzDrawSegments[very thick, color=#3](A7,A8 A8,A9 A9,A5)
		\tkzDrawSegments[thin, color=#3, dashed, opacity=0.75](A5,A6 A6,A7)

%		\tkzLabelPoints[above](A0,A1,A2,A3,A4,A5,A6,A7,A8,A9);
	\end{scope}
}


